// Query module for statistics computed from Cricsheet ball-by-ball data.
// Data files are generated by scripts/cricsheet/build.js into api/data/cricsheet/.
// Every public use of these figures must show ATTRIBUTION (ODC Attribution License).
//
// Exports: getMeta(), getRecords(format, gender), getHeadToHead(teamA, teamB, format?, gender?),
//          getVenue(name), ATTRIBUTION.
// None of the functions throw on bad input; they return null or [].
"use strict";

const fs = require("fs");
const path = require("path");

const ATTRIBUTION =
  "Contains information from Cricsheet (https://cricsheet.org), which is made available under the " +
  "ODC Attribution License (https://opendatacommons.org/licenses/by/1-0/); figures are computed by " +
  "livecricketzone.com from Cricsheet's ball-by-ball data, which does not include every international match " +
  "(coverage starts between 2001 and 2009 depending on format, early years are sparse, and matches involving " +
  "Afghanistan's men's team are withheld), so older careers and some totals are incomplete.";

// Each file is read with a literal path so Vercel's file tracing bundles it with the function.
const readers = {
  meta: () => fs.readFileSync(path.join(__dirname, "data/cricsheet/meta.json"), "utf8"),
  records: () => fs.readFileSync(path.join(__dirname, "data/cricsheet/records.json"), "utf8"),
  h2h: () => fs.readFileSync(path.join(__dirname, "data/cricsheet/h2h.json"), "utf8"),
  venues: () => fs.readFileSync(path.join(__dirname, "data/cricsheet/venues.json"), "utf8"),
};
const cache = {};
function load(name) {
  if (!(name in cache)) {
    try { cache[name] = JSON.parse(readers[name]()); } catch (_) { cache[name] = null; }
  }
  return cache[name];
}

const FORMATS = ["test", "odi", "t20i"];

function normFormat(f) {
  const k = String(f == null ? "" : f).toLowerCase().replace(/[^a-z0-9]/g, "");
  if (["test", "tests"].includes(k)) return "test";
  if (["odi", "odis", "oneday", "onedayinternational"].includes(k)) return "odi";
  if (["t20i", "t20is", "t20", "t20s", "it20"].includes(k)) return "t20i";
  return null;
}

function normGender(g) {
  const k = String(g == null ? "" : g).toLowerCase().replace(/[^a-z]/g, "");
  if (["men", "male", "m", "mens"].includes(k)) return "men";
  if (["women", "female", "w", "womens", "ladies"].includes(k)) return "women";
  return null;
}

// Same rules as scripts/cricsheet/venues.js compact().
function compact(s) {
  return String(s || "")
    .normalize("NFKD").replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/&/g, " and ")
    .trim()
    .replace(/^the\s+/, "")
    .replace(/[^a-z0-9]/g, "");
}

// Short names and alternative spellings used by score sites, mapped to Cricsheet team names.
const TEAM_ALIASES = {
  ind: "India", aus: "Australia", eng: "England", nz: "New Zealand", sa: "South Africa", rsa: "South Africa",
  pak: "Pakistan", sl: "Sri Lanka", slk: "Sri Lanka", ban: "Bangladesh", bd: "Bangladesh", wi: "West Indies",
  windies: "West Indies", zim: "Zimbabwe", ire: "Ireland", sco: "Scotland", ned: "Netherlands", nl: "Netherlands",
  holland: "Netherlands", nam: "Namibia", nep: "Nepal", uae: "United Arab Emirates", usa: "United States of America",
  unitedstates: "United States of America", can: "Canada", oma: "Oman", png: "Papua New Guinea", hk: "Hong Kong",
  ken: "Kenya", uga: "Uganda", tha: "Thailand", mas: "Malaysia", mly: "Malaysia", sgp: "Singapore", sin: "Singapore",
  jer: "Jersey", gue: "Guernsey", qat: "Qatar", kuw: "Kuwait", bhr: "Bahrain", ber: "Bermuda", afg: "Afghanistan",
  swaziland: "Eswatini", czechia: "Czech Republic", turkiye: "Turkey", cotedivoire: "Ivory Coast",
  easttimor: "Timor-Leste", korea: "South Korea", worldxi: "ICC World XI", iccworldxi: "ICC World XI",
};

// "New Zealand Women", "India W", "INDW", "NZ-W", "England (W)" -> { key, women: true }
function parseTeam(input) {
  let s = String(input == null ? "" : input).trim().toLowerCase();
  let women = false;
  const suffix = /[\s\-_]*(\(w\)|women'?s?|woman|ladies|\bw)$/;
  if (suffix.test(s)) { s = s.replace(suffix, ""); women = true; }
  s = s.replace(/[\s\-_]*\bmen'?s?$/, "");
  let key = compact(s);
  if (!women && key.length >= 3 && key.length <= 5 && key.endsWith("w") && TEAM_ALIASES[key.slice(0, -1)]) {
    key = key.slice(0, -1); women = true;
  }
  return { key, women };
}

function resolveTeam(key, names) {
  if (!key) return null;
  const byKey = new Map(names.map((n) => [compact(n), n]));
  if (byKey.has(key)) return byKey.get(key);
  const alias = TEAM_ALIASES[key];
  if (alias) return byKey.get(compact(alias)) || null;
  if (key.length >= 3) {
    const hits = names.filter((n) => compact(n).startsWith(key));
    if (hits.length === 1) return hits[0];
  }
  return null;
}

function teamNames(block) {
  const set = new Set();
  for (const k of Object.keys(block || {})) for (const t of k.split("|")) set.add(t);
  return [...set];
}

function orient(rec, a, b, format, gender, meta) {
  const tb = rec.tieBreakWins || {};
  return {
    format, gender,
    teamA: { name: a, wins: rec.wins[a] || 0, ...(tb[a] ? { tieBreakWins: tb[a] } : {}) },
    teamB: { name: b, wins: rec.wins[b] || 0, ...(tb[b] ? { tieBreakWins: tb[b] } : {}) },
    matches: rec.matches, ties: rec.ties, draws: rec.draws, noResults: rec.noResults,
    firstDate: rec.firstDate, lastDate: rec.lastDate,
    last5: rec.last5,
    coverage: (meta && meta.perFormat && meta.perFormat[format] && meta.perFormat[format][gender]) || null,
    source: "Cricsheet",
  };
}

function getMeta() {
  return load("meta");
}

function getRecords(format, gender) {
  try {
    const f = normFormat(format);
    const g = gender == null || gender === "" ? "men" : normGender(gender);
    const data = load("records");
    if (!f || !g || !data || !data[f] || !data[f][g]) return null;
    return Object.assign({ format: f, gender: g }, data[f][g]);
  } catch (_) { return null; }
}

// With a format: one oriented record or null. Without: an array over formats (possibly empty).
function getHeadToHead(teamA, teamB, format, gender) {
  const many = format == null || format === "";
  try {
    const data = load("h2h");
    const meta = load("meta");
    const fmts = many ? FORMATS : [normFormat(format)].filter(Boolean);
    if (!data || !fmts.length) return many ? [] : null;
    const pa = parseTeam(teamA);
    const pb = parseTeam(teamB);
    // A "Women" suffix on either name wins over the gender argument.
    const g = pa.women || pb.women ? "women" : gender == null || gender === "" ? "men" : normGender(gender);
    if (!g) return many ? [] : null;
    const out = [];
    for (const f of fmts) {
      const block = data[f] && data[f][g];
      if (!block) continue;
      const names = teamNames(block);
      const a = resolveTeam(pa.key, names);
      const b = resolveTeam(pb.key, names);
      if (!a || !b || a === b) continue;
      const rec = block[[a, b].sort().join("|")];
      if (rec) out.push(orient(rec, a, b, f, g, meta));
    }
    return many ? out : out[0] || null;
  } catch (_) { return many ? [] : null; }
}

// Tolerant lookup on the venue's leading part ("Eden Gardens, Kolkata" -> Eden Gardens).
function getVenue(name) {
  try {
    const data = load("venues");
    const q = String(name == null ? "" : name).trim();
    if (!data || !Array.isArray(data.venues) || !q) return null;
    const parts = q.split(",").map((p) => p.trim()).filter(Boolean);
    const lead = compact(parts[0] || q);
    const whole = compact(q);
    const pa = data.placeAliases || {};
    const places = parts.slice(1).map((p) => { const k = compact(p); return pa[k] || k; }).filter(Boolean);
    const vs = data.venues;

    let hits = vs.filter((v) => v.keys.includes(lead) || v.keys.includes(whole));
    if (!hits.length && lead.length >= 5) {
      hits = vs.filter((v) => v.keys.some((k) => k.length >= 5 && (k.startsWith(lead) || lead.startsWith(k))));
    }
    if (!hits.length) return null;
    if (hits.length > 1 && places.length) {
      const byPlace = hits.filter((v) => places.some((p) => v.places.includes(p) || compact(v.city) === p));
      if (byPlace.length) hits = byPlace;
    }
    hits.sort((x, y) => y.matches - x.matches);
    return Object.assign({ source: "Cricsheet" }, hits[0]);
  } catch (_) { return null; }
}

module.exports = { getMeta, getRecords, getHeadToHead, getVenue, ATTRIBUTION };
